import{_ as s,a0 as p,w as a,s as l,ao as u,I as r,x as e,a1 as n,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const D=JSON.parse(`{"title":"开源是冷酷无情的：谷歌Chris DiBona访谈 | LCTT x X-CMD","titleTemplate":false,"description":"开源是冷酷无情的：谷歌Chris DiBona访谈 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"开源是冷酷无情的：谷歌Chris DiBona访谈 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"开源是冷酷无情的：谷歌Chris DiBona访谈 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Open source is brutal- an interview with Google's Chris DiBona","title":"开源是冷酷无情的：谷歌Chris DiBona访谈","tag":"201310","desc":""},"relativePath":"201310/Open source is brutal- an interview with Google's Chris DiBona.md","filePath":"[post].md"}`),d={name:"201310/Open source is brutal- an interview with Google's Chris DiBona.md"};function m(C,i,h,f,T,x){const t=p("Link");return a(),l("div",null,[i[11]||(i[11]=u('<h1 id="开源是冷酷无情的-谷歌chris-dibona访谈" tabindex="-1">开源是冷酷无情的：谷歌Chris DiBona访谈 <a class="header-anchor" href="#开源是冷酷无情的-谷歌chris-dibona访谈" aria-label="Permalink to “开源是冷酷无情的：谷歌Chris DiBona访谈”">​</a></h1><p><img src="https://opensource.com/sites/default/files/imagecache/image-full-size/images/law/LAW_imaginationcrucial.png" alt="img"></p><p>Chris DiBona是谷歌开源总监。他也是开源界杰出的领军人物之一，这还要追溯到他的大学时期，那时他对Linux可谓一见钟情。</p><p>在今年的 “一切皆开源” 大会上，Christ将会提供谷歌目前的开源软件活动的最新消息以及对过去的回顾，还有Android的起源和现况。</p><p>我遇到了Christ，我们讨论了他最喜爱的Linux发行版、开源的无情法则以及他对谷歌作为业界领袖应有的责任的看法。</p><p>以下是访谈详情。</p><p>###问：对于你加入谷歌并且在开源部门展开工作，有那些方面是我们所不知道的？</p><p>答： 第一次使用Linux是在上学的时候，由于当时选修了操作系统课程，因此，我需要写一些有关客户端/服务器的东西。出乎意料的是，那时候Sun工作站实验室很热闹，因为公开探讨问题的风气使然，编码味十足，使用的终端跑得相当慢。我在想，瓶颈在哪，不妨就用一直都摆放在家里的一台486-16上试试这个linux到底怎么样。这是我有史以来最棒的一次决定！从此我喜欢上了linux系统。linux太棒了，运行很快，与其他unix系统相比，功能齐全。OS这门课程，我也得了A。</p><p>###问：下面这个问题的危险程度跟询问你最喜欢的球队一样，你最喜欢哪个linux发行版？</p><p>答： 哈！如果轻率地回答，那么是Android，因为Android是基于linux内核的，而我对它的使用频度远远超过其他一些东西。尽管通常情况下讨论Android时，多数人都不把它当做一个发行版。我现在正在一个Ubuntu/Debian衍生版本上运行的Chrome浏览器中回复你这个问题的回答，我在谷歌计算引擎上运行的是Debian，在家里则经常用Fedora。出席公共场合的时候，大多数情况下我携带Chromebook，感觉用它最安全。那么最喜欢的就是Android。</p><p>###问：2004年加入谷歌之前，你在开源和linux领域投入了许多精力，是什么原因促使你加入谷歌?</p><p>答： 从事了一小段时间咨询方面的工作以后，当我决定开始全职工作，谷歌的offer对我来说最富有吸引力。 成为谷歌开源人、白手起家开始创业的想法深深地吸引着我。我感觉无论过去还是现在，谷歌始终在计算机科学领域做着有趣的事情，而且以它独有的方式吸引着我，这些是其他offer所不具备的。</p><p>###问：你不但指导各种项目的开发，而且也参与了Google Ventures，为该项目的启动注资，那么你在一个项目中想要寻求什么，是什么让你说出“是的，我就是想帮你”这样的话 ?</p><p>答： 呃，坦白说，我希望它能够做的有趣。对于Google Ventures，我并不需要过多的深入其中，而开源问题就不同了，有趣而且参与者众多。</p><p>###问：多年前的一次采访中你曾经说过：“谷歌与开源社区同行。赞助意味着责任，这是相当严肃的一件事情。”谷歌是否打算避免在自己参与的社区中担责，二者之间存在必然联系吗？</p><p>答： 我想是这样的。我希望谷歌工程师和非谷歌开源界的工程师都能把对方看做计算机科学领域的同侪。我们得意识到，对开源项目的广泛资助预示着责任，比如项目控制，大家都知道，事情就应该这么做，即使真的没什么联系。</p><p>###问：你曾经称开源是“无情”的,具体是什么意思?</p><p>答： 呃，我还以为你会问为什么开源可以行得通，什么时候会考虑开源软件工程管理在业内是如何运作，但是你没有。分散的、不同特性的团队在公司里相当难运作，但是在开源领域，可以创作出世界级非常优秀的软件。为什么会这样？</p><p>因为我认为，在开源项目中，你可以选择只和富有成效的人一起工作而忽视其他人。这种行为被理解为非常尖刻和排斥性的。然而实情原本就如此：无情并别排斥那些无所贡献的人。</p><p>然而这就是为什么项目克隆如此重要。无论出于什么原因，如果一个人被排斥在一个项目之外，那么他们可以克隆该项目然后使该项目朝着一个新方向发展。假如他们的想法及实现优于先前被拒绝加入的项目，那么，好吧，这次克隆成为新的现实，而那些拒绝别的开发者加入的家伙现在则尝到了被拒绝的滋味。</p><p>所以，我想说，开源世界是一个适者生存、优胜劣汰的残酷机制，但是这样却能生产出高质量的软件产品。诚然，对新手来说比较难上手……</p><p>###问：14年前，你在O&#39;Reilly出版过一本有关开源的书。这些年开源领域是否了发生大的变化？你认为将来开源模式会取代专有模式吗？</p><p>答： 开源界确实发生了一些变化，非常显著的一点就是公司里从事开源工作的人数的增长。而且我还觉察到学术界参与开源的人数有所下降，我把它归咎于技术转让专利申请，对代码许可权确实是个障碍。类似的，一些来自大学和公司的开源代码不足以称之为开源，因为围绕着专利要应付相当多的问题。我很想说要不是有专利授权许可，我们应该都持怀疑态度，但是在这个时候说这样的话就有一点走极端了。</p><hr>',24)),r("p",null,[i[1]||(i[1]=e("via: ",-1)),n(t,{href:"https://opensource.com/business/13/10/interview-chris-dibona"},{default:o(()=>[...i[0]||(i[0]=[e("https://opensource.com/business/13/10/interview-chris-dibona",-1)])]),_:1})]),r("p",null,[i[4]||(i[4]=e("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...i[2]||(i[2]=[e("LCTT",-1)])]),_:1}),i[5]||(i[5]=e(" 原创翻译，",-1)),n(t,{href:"http://linux.cn/"},{default:o(()=>[...i[3]||(i[3]=[e("Linux中国",-1)])]),_:1}),i[6]||(i[6]=e(" 荣誉推出",-1))]),r("p",null,[i[9]||(i[9]=e("译者：",-1)),n(t,{href:"https://github.com/l3b2w1"},{default:o(()=>[...i[7]||(i[7]=[e("l3b2w1",-1)])]),_:1}),i[10]||(i[10]=e(" 校对：",-1)),n(t,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...i[8]||(i[8]=[e("Caroline",-1)])]),_:1})])])}const _=s(d,[["render",m]]);export{D as __pageData,_ as default};
